export function getOfficeCoords(postcode, province) {
  if (KNOWN_OFFICE_COORDS[postcode]) {
    return KNOWN_OFFICE_COORDS[postcode];
  }
  const base = PROVINCE_CENTERS[province] || REGION6_CENTER;
  return [base.lat, base.lng];
}

export const compactMoney = (val) => {
  if (val == null || !Number.isFinite(val)) return '0';
  const abs = Math.abs(val);
  const sign = val < 0 ? '-' : '';
  if (abs >= 1000000000) return `${sign}${(abs / 1000000000).toFixed(2)}B`;
  if (abs >= 1000000) return `${sign}${(abs / 1000000).toFixed(2)}M`;
  if (abs >= 1000) return `${sign}${(abs / 1000).toFixed(1)}k`;
  return `${sign}${abs.toFixed(0)}`;
};
